package io.github.angbang852.manjiao.util

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.BitmapShader
import android.graphics.Canvas
import android.graphics.LinearGradient
import android.graphics.Paint
import android.graphics.RadialGradient
import android.graphics.Shader
import android.graphics.drawable.BitmapDrawable
import android.graphics.drawable.Drawable
import android.util.Base64

object IconData {
    // 新版模块图标（= app launcher 图标，mipmap-xxxhdpi/ic_launcher.png）
    private const val PNG_BASE64 = ""

    @Volatile private var cache: Drawable? = null

    fun get(ctx: Context): Drawable {
        cache?.let { return it }
        val bytes = Base64.decode(PNG_BASE64, Base64.DEFAULT)
        val src = BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
        // 快手分享面板风格：launcher 图标整图圆形裁剪（BitmapShader 裁圆），
        // 外圈白色描边——与其他分享图标同款整圆设计，不再合成橙底嵌方图
        val size = 192
        val out = Bitmap.createBitmap(size, size, Bitmap.Config.ARGB_8888)
        val c = Canvas(out)
        val p = Paint(Paint.ANTI_ALIAS_FLAG or Paint.FILTER_BITMAP_FLAG)
        val shader = BitmapShader(src, Shader.TileMode.CLAMP, Shader.TileMode.CLAMP)
        val m = android.graphics.Matrix()
        m.setScale(size / src.width.toFloat(), size / src.height.toFloat())
        shader.setLocalMatrix(m)
        p.shader = shader
        val r = size / 2f
        c.drawCircle(r, r, r, p)
        p.shader = null
        // 白色描边
        p.style = Paint.Style.STROKE
        p.strokeWidth = size * 0.03f
        p.color = 0xFFFFFFFF.toInt()
        c.drawCircle(r, r, r - p.strokeWidth / 2f, p)
        p.style = Paint.Style.FILL
        cache = BitmapDrawable(ctx.resources, out)
        return cache!!
    }
}
